    #[test]
    fn should_detect_stuck_session() {
        let mut state = SessionContextState::new("test".to_string());

        // Add similar queries
        for _i in 0..5 {
            state.record_activity(
                ActivityType::Query,
                "how to fix error".to_string(),
                serde_json::json!({}),
            );
        }

        assert!(state.is_stuck());
    }

    #[test]
    fn should_not_detect_stuck_with_varied_queries() {
        let mut state = SessionContextState::new("test".to_string());

        state.record_activity(
            ActivityType::Query,
            "how to fix database error".to_string(),
            serde_json::json!({}),
        );
        state.record_activity(
            ActivityType::Query,
            "how to configure api endpoint".to_string(),
            serde_json::json!({}),
        );
        state.record_activity(
            ActivityType::Query,
            "how to deploy application".to_string(),
            serde_json::json!({}),
        );

        assert!(!state.is_stuck());
    }

    #[test]
    fn should_track_error_count() {
        let mut state = SessionContextState::new("test".to_string());

        state.record_activity(
            ActivityType::Error,
            "error 1".to_string(),
            serde_json::json!({}),
        );
        state.record_activity(
            ActivityType::Error,
            "error 2".to_string(),
            serde_json::json!({}),
        );
        state.record_activity(
            ActivityType::Query,
            "query".to_string(),
            serde_json::json!({}),
        );

        assert_eq!(state.recent_error_count, 2);
    }

    #[test]
    fn should_respect_push_rate_limit() {
        let mut state = SessionContextState::new("test".to_string());

        assert!(state.can_push()); // First push allowed

        state.record_push();
        assert!(!state.can_push()); // Too soon
    }
}

//! RAG ingestion pipeline for repomix content.
//!
//! Pipeline: zip → repomix parse → enrich → chunk → Voyage embed → Qdrant upsert
//!
//! Each Qdrant point payload carries rich metadata for hover display:
//!   repo, file_path, language, symbols, doc_comments, imports, tags,
//!   is_test, line_start, line_end, chunk_index, total_chunks, content_hash

use anyhow::{Context, Result};
use qdrant_client::{
    qdrant::{
        vectors_config::Config as VectorsConfigEnum, Condition, CreateCollectionBuilder, Distance,
        Filter, PointStruct, ScoredPoint, SearchPointsBuilder, UpsertPointsBuilder,
        VectorParamsBuilder, VectorsConfig,
    },
    Payload, Qdrant, QdrantError,
};
use regex::Regex;
use reqwest::Client;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{
    collections::HashMap,
    io::{BufRead, BufReader},
    path::Path,
    sync::OnceLock,
    time::Duration,
};
use tracing::{info, warn};

// ─── constants ───────────────────────────────────────────────────────────────

pub const DEFAULT_COLLECTION: &str = "repomix_rag";
const VECTOR_DIM: u64 = 1024; // voyage-4 default
const CHUNK_LINES: usize = 80; // ~2 kB of code per chunk
const OVERLAP_LINES: usize = 12;
const VOYAGE_PUBLIC_URL: &str = "https://api.voyageai.com/v1/embeddings";
const VOYAGE_MONGODB_URL: &str = "https://ai.mongodb.com/v1/embeddings";
const VOYAGE_BATCH: usize = 32; // points per upsert batch
const VOYAGE_RATE_DELAY_MS: u64 = 120; // ms between Voyage calls

// ─── extracted file metadata ──────────────────────────────────────────────────

